 const activeIds=new Set(data.catalog.map(x=>x.projectId));const offers=(S.streamingOffers||[]).filter(x=>x.serviceId===svc.id&&x.status!=='declined'&&x.status!=='booked'&&x.expiresWeek>=S.week);
 return panel('Streaming service · '+esc(svc.name),`<div class="dashboard-grid"><div>${metric('PAID SUBSCRIPTION GROSS',fmt(data.grossReceipts),'Recorded outside cash, not project rights income','◉')}${metric('ACTIVE LICENSED TITLES',String(data.catalog.length),'Only lawful unexpired streaming windows','▣')}</div><div>${metric('ACTIVE SUBSCRIBERS',suffix(Object.values(data.regions).reduce((n,r)=>n+r.subscribers,0)),'Regional customers · churn included','◈')}${metric('SERVICE RUNNING COST',fmt(data.runningCost),fmt(svc.monthlyCost)+' / monthly close','▥')}</div></div>
 <p class="panel-sub">Monthly subscription tier: <strong>${esc(svc.tier)} · ${fmt(svc.price)}</strong>. Change prices without inventing earlier subscriptions: ${Object.keys(E.STREAM_TIERS).filter(k=>k!==svc.tier).map(k=>btn(k+' · '+fmt(E.STREAM_TIERS[k]),`data-tv-tier="${k}" data-tv-service="${esc(svc.id)}"`)).join(' ')}</p>
 <p class="panel-sub">By region: ${Object.entries(data.regions).map(([k,r])=>esc(k)+' '+suffix(r.subscribers)+' subscribers / '+fmt(r.paidGross)).join(' · ')||'No paying subscribers yet'}. Subscriber numbers are modeled; paid cash is recorded.</p>
 <p class="panel-sub">Catalog: ${data.catalog.map(w=>esc(w.title)+' · '+w.expiresIn+' weeks left').join(' · ')||'Empty. License existing owned TV/film releases or negotiate outside titles.'}</p>
 <div class="head-actions" style="flex-wrap:wrap">${owned.filter(p=>!activeIds.has(p.id)&&!(S.streamingWindows||[]).some(w=>w.serviceId===svc.id&&w.projectId===p.id&&w.endWeek>S.week)).slice(-CFG.tuning_ui.streamingBusinessPanel__002).map(p=>btn('Stream '+esc(p.title)+' · 52 weeks',`data-tv-stream-owned="${esc(p.id)}" data-tv-service="${esc(svc.id)}"`)).join('')}</div>
 ${offers.map(o=>`<div class="inbox-item"><div><strong>${esc(S.projects.find(p=>p.id===o.projectId)?.title||'Catalog offer')}</strong><p>${esc(E.company(S,o.ownerId)?.name||'Independent producer')} · ${esc(o.status)} · ${fmt(o.status==='counter'?o.counterFee:o.acceptedFee)} · valid through ${esc(weekLabel(o.expiresWeek))}</p>${o.status==='counter'?btn('Accept counter',`data-tv-offer-answer="${esc(o.id)}" data-tv-agree="true"`)+btn('Decline',`data-tv-offer-answer="${esc(o.id)}" data-tv-agree="false"`):btn('Book accepted rights',`data-tv-book-external="${esc(o.id)}"`)}</div></div>`).join('')}
 ${rivals.length?`<p class="panel-sub">Independent catalog rights must be offered and accepted. We cannot unilaterally take a rival's television or film.</p><div class="head-actions" style="flex-wrap:wrap">${rivals.filter(p=>!activeIds.has(p.id)&&!offers.some(o=>o.projectId===p.id)).map(p=>btn('Offer for '+esc(p.title),`data-tv-request-external="${esc(p.id)}" data-tv-service="${esc(svc.id)}"`)).join('')}</div>`:''}`);
