function slotInfo(slot){try{const raw=localStorage.getItem(SLOT_PREFIX+slot);if(!raw)return 'Empty';const x=JSON.parse(raw);return esc((x.label||x.name)+' · '+x.name+' · Y'+x.year);}catch(e){return 'Unavailable';}}
function slotName(slot){try{const raw=localStorage.getItem(SLOT_PREFIX+slot);return raw?JSON.parse(raw).label||'':'';}catch(e){return '';}}
// Update 50: explicit names and keyboard containment for consequential decisions.
// One dialog is visible at a time; routine work remains accessible without a mouse.
let modalReturnFocus50=null,controlId50=0;
function labelControls50(root){
 if(!root)return;
 root.querySelectorAll('.form-field').forEach(field=>{
  const label=field.querySelector('label');
  const control=field.querySelector('input:not([type="hidden"]),select,textarea');
  if(!label||!control||control.getAttribute('aria-label')||control.getAttribute('aria-labelledby'))return;
  if(!control.id)control.id='studio-field-'+(++controlId50);
  if(!label.htmlFor)label.htmlFor=control.id;
 });
}
function showModal(html){
 const host=$('modal');
 if(!host.classList.contains('open')&&document.activeElement&&!host.contains(document.activeElement))modalReturnFocus50=document.activeElement;
 host.innerHTML=`<div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="studio-dialog-title">${html}</div>`;
 const title=host.querySelector('.modal-head h2')||host.querySelector('h2');
 if(title)title.id='studio-dialog-title';
 else host.querySelector('[role="dialog"]').setAttribute('aria-label','Studio decision');
 host.classList.add('open');labelControls50(host);
 const first=host.querySelector('input:not([type="hidden"]),select,button');first?.focus();
}
function closeModal(){
 const host=$('modal');host.classList.remove('open');host.innerHTML='';
 const target=modalReturnFocus50;modalReturnFocus50=null;
 if(target?.isConnected)target.focus();else $('content')?.focus();
}
const modalHead=(title)=>`<div class="modal-head"><h2>${title}</h2><button type="button" class="modal-close" data-close-modal aria-label="Close">×</button></div>`;
function newGameModal(){const era=1;showModal(`${modalHead('Create your entertainment world')}<p class="page-sub" style="margin-top:-13px;margin-bottom:18px">Choose your starting era and begin as a new company. No rival assets are inherited.</p><form id="new-game-form"><div class="form-grid"><div class="form-field"><label>START WORLD YEAR</label><select name="era" id="new-era">${[1,CFG.tuning_ui.newGameModal__001,CFG.tuning_ui.newGameModal__002,CFG.tuning_ui.newGameModal__003,CFG.tuning_ui.newGameModal__004].map(x=>`<option value="${x}" ${x===era?'selected':''}>Year ${x}${x===CFG.tuning_ui.newGameModal__005?' · Mature entertainment era':''}</option>`).join('')}</select></div><div class="form-field"><label>COMPANY ORIGIN</label><select name="origin" id="new-origin">${originOptions(1)}</select></div><div class="form-field span2"><label>COMPANY NAME</label><input name="companyName" value="Syndicate Works" maxlength="${CFG.forms.htmlValues.newGameModal__maxlength_001}" required></div><div class="form-field"><label>FOUNDER NAME</label><input name="founder" value="Alex Morgan" maxlength="${CFG.forms.htmlValues.newGameModal__maxlength_002}" required></div><div class="form-field"><label>FOUNDER AGE</label><input type="number" name="age" value="${CFG.forms.htmlValues.newGameModal__value_001}" min="${CFG.forms.htmlValues.newGameModal__min_001}" max="${CFG.forms.htmlValues.newGameModal__max_001}"></div><div class="form-field"><label>FOUNDER BACKGROUND</label><select name="background"><option value="editorial">Editorial · publishing creative edge</option><option value="finance">Finance · commercial planning</option><option value="production">Production · hands-on delivery</option></select></div><div class="form-field"><label>FOUNDER FOCUS</label><select name="founderFocus"><option value="creative">Creative quality</option><option value="commercial">Commercial reach</option><option value="people">Team leadership</option></select></div><div class="form-field"><label>WORLD SEED</label><input name="seed" value="STUDIO-114" maxlength="${CFG.forms.htmlValues.newGameModal__maxlength_003}" required></div><div class="form-field"><label>HOME REGION · COMPANY PROFIT TAX</label><select name="homeRegion">${E.REGIONS.map(r=>`<option value="${esc(r.name)}">${esc(r.name)} · ${Math.round(r.profitTaxRate*CFG.tuning_ui.newGameModal__006)}%</option>`).join('')}</select></div><div class="form-field"><label>WORLD SCALE</label><select name="worldScale" aria-label="Background competitor world scale"><option value="${CFG.forms.htmlValues.newGameModal__value_002}" selected>Focused · quick turns</option><option value="${CFG.forms.htmlValues.newGameModal__value_003}">Broad · more competitors</option><option value="${CFG.forms.htmlValues.newGameModal__value_004}">Large · more demanding</option></select></div><div class="form-field"><label>STARTING CAPITAL</label><select name="startingCapital"><option value="lean">Lean · 72% of base</option><option value="standard" selected>Standard</option><option value="funded">Funded · 145% of base</option></select></div><div class="form-field"><label>WORLD MATURITY</label><select name="worldMaturity"><option value="emerging">Emerging rivals · less capital</option><option value="standard" selected>Standard</option><option value="developed">Developed rivals · better funded</option></select></div><div class="form-field"><label>DETAILED AI RIVALS AT START</label><select name="aiCount"><option value="">Era default</option><option value="${CFG.forms.htmlValues.newGameModal__value_005}">2 · quieter world</option><option value="${CFG.forms.htmlValues.newGameModal__value_006}">5 · busy world</option><option value="${CFG.forms.htmlValues.newGameModal__value_007}">9 · competitive world</option><option value="${CFG.forms.htmlValues.newGameModal__value_008}">12 · demanding simulation</option></select></div><div class="form-field"><label>CONSUMER POPULATION</label><select name="populationScale"><option value="${CFG.forms.htmlValues.newGameModal__value_009}">Small · 50% market</option><option value="${CFG.forms.htmlValues.newGameModal__value_010}" selected>Standard</option><option value="${CFG.forms.htmlValues.newGameModal__value_011}">Large · 175% market</option></select></div><div class="form-field"><label>ACTIVE REGIONS</label><select name="regionCount"><option value="${CFG.forms.htmlValues.newGameModal__value_012}">2 regions · focused market</option><option value="${CFG.forms.htmlValues.newGameModal__value_013}">3 regions</option><option value="${CFG.forms.htmlValues.newGameModal__value_014}" selected>4 regions · full market</option></select></div><div class="form-field"><label>TECH DISCOVERY SPEED</label><select name="discoveryPace"><option value="slow">Slow</option><option value="standard" selected>Normal</option><option value="fast">Fast</option></select></div><div class="form-field"><label>TECH ADOPTION SPEED</label><select name="adoptionPace"><option value="slow">Slow</option><option value="standard" selected>Normal</option><option value="fast">Fast</option></select></div><div class="form-field"><label>STUDIO CAPABILITY PACE</label><select name="capabilityPace"><option value="deliberate">Deliberate · higher entry and team cost</option><option value="standard" selected>Normal</option><option value="accelerated">Accelerated · lower entry and team cost</option></select></div><div class="form-field"><label>GAME DEPTH</label><select name="depth" id="new-depth" aria-label="Game depth">${Object.keys(CFG.depth.LABELS).map(m=>`<option value="${m}" ${m===CFG.depth.DEFAULT?'selected':''}>${esc(CFG.depth.LABELS[m].name)} · ${esc(CFG.depth.LABELS[m].blurb)}</option>`).join('')}</select><small class="input-note">You can change depth later in Settings.</small></div><div class="form-field"><label>DIFFICULTY</label><select name="difficulty"><option value="casual">Casual · extra cash</option><option value="standard" selected>Standard</option><option value="challenging">Challenging · lower cash</option></select></div></div><div class="modal-bottom"><p>Large rival counts and Large world scale can make turns and saves slower. Low cash and small populations increase risk. Technology pace changes discoveries and adoption, NEVER the fixed four industry debut years.</p><button class="btn btn-primary" type="submit">Found my studio →</button></div></form>`);}
