function repayBankModal(){
 const loan=(S.loans||[]).filter(l=>l.debtorId===S.playerId&&l.status!=='paid').at(-1);
 if(!loan)return notify('There is no outstanding bank loan.','error');
 const c=E.player(S),overhead=E.liquidityForecast(S).weeklyOverhead;
 const owed=Math.round((loan.principalOutstanding+loan.interestArrears)*CFG.tuning_ui.owed__001)/CFG.tuning_ui.owed__002;
 const limit=Math.round(Math.max(0,Math.min(owed,c.finance.cash-overhead*CFG.tuning_ui.limit__001))*CFG.tuning_ui.limit__002)/CFG.tuning_ui.limit__003;
 if(limit<=0)return notify('Not enough cash to repay early while keeping a two-week operating buffer.','error');
 showModal(`${modalHead('Optional early bank repayment')}<p class="page-sub">Normal monthly payments are automatic. You can voluntarily reduce the principal to save future interest. Any previously accrued interest is settled first.</p><form id="bank-repay-form"><input type="hidden" name="loanId" value="${esc(loan.id)}"><div class="form-grid"><div class="form-field"><label>REPAYMENT AMOUNT</label><input type="number" name="amount" min="${CFG.forms.htmlValues.repayBankModal__min_001}" max="${limit}" step="${CFG.forms.htmlValues.repayBankModal__step_001}" value="${Math.min(limit,CFG.tuning_ui.repayBankModal__001)}" required></div><div class="form-field"><label>MAXIMUM SAFE PAYMENT</label><div class="section-note neutral">${fmt(limit)}</div></div></div><div class="section-note neutral" style="margin-top:12px">Interest due: ${fmt(loan.interestArrears)} · principal: ${fmt(loan.principalOutstanding)}. You will retain at least two weeks of operating cash. This does not change past profits.</div><div class="modal-bottom"><p>Future scheduled installments remain automated and reduce when principal is prepaid.</p><button type="submit" class="btn btn-primary">Repay bank</button></div></form>`);
}
